// App-origin service worker.
// - Serves verified app files the loader installed, and the PWX runtime, from the device.
// - Checks every runtime file against hashes pinned in this script each time it serves it,
//   and applies its own headers, so nothing written to CacheStorage can change the runtime.
// - Serves PWX pages and app documents only into frames, never as a tab.
// BEGIN PINNED RUNTIME (generated by tools/pin-runtime.mjs; do not edit by hand)
const PINNED = {
  "/__pwx/bootstrap.html": "sha256-9JrT65ViQ0oqbSFmzplt36pXf3XbXBoIDwKedw2D+v0=",
  "/__pwx/bootstrap.js": "sha256-klCmLaVn6xckiKTkPkUo2/mxymtXL++tzIFGn/z9i4I=",
  "/__pwx/strict.html": "sha256-uGg0JedU1IFHz3RYE0kPVzdLwjEZw5vw1MkDMV1UVYE=",
  "/__pwx/renderer.js": "sha256-ROxnSPFpYIq24Vtmlo1EUhnS5nUwpt2NahCEeOKQbOU=",
  "/__pwx/guard.js": "sha256-T5G742sbqECNwXC5VeaEMRdp6J5JL0nRwNQrr3474YI=",
  "/__pwx/ui.css": "sha256-pwAlPyW8ZnERztqY6NLPsZMz89x6BBjG34LjRZ61jPw="
};
// END PINNED RUNTIME
const LOADER_ORIGIN = "__PWX_LOADER_ORIGIN__"; // substituted by the server that serves this script
const RUNTIME = "pwx-runtime-v1";
const STRICT_CSP = `default-src 'none'; script-src 'self'; worker-src data:; img-src blob:; style-src 'self'; font-src 'none'; connect-src 'none'; frame-src 'none'; base-uri 'none'; form-action 'none'; frame-ancestors ${LOADER_ORIGIN}`;
const HEADERS = {
  "/__pwx/bootstrap.html": { "Content-Type": "text/html; charset=utf-8", "Content-Security-Policy": `default-src 'self'; script-src 'self'; frame-ancestors ${LOADER_ORIGIN}` },
  "/__pwx/strict.html": { "Content-Type": "text/html; charset=utf-8", "Content-Security-Policy": STRICT_CSP },
  "/__pwx/bootstrap.js": { "Content-Type": "text/javascript" },
  "/__pwx/renderer.js": { "Content-Type": "text/javascript" },
  "/__pwx/guard.js": { "Content-Type": "text/javascript" },
  "/__pwx/ui.css": { "Content-Type": "text/css" },
};
const FRAME_ONLY = (p) => p === "/__pwx/bootstrap.html" || p.startsWith("/__pwx/strict") || p.startsWith("/app/");

async function hashOf(buf) {
  const d = new Uint8Array(await crypto.subtle.digest("SHA-256", buf));
  return "sha256-" + btoa(String.fromCharCode(...d));
}
// Serve a runtime file only if its bytes match the pinned hash. A tampered cache entry is
// replaced from the network if the network copy matches; otherwise nothing is served.
async function runtimeFile(path) {
  const cache = await caches.open(RUNTIME);
  for (const source of ["cache", "network"]) {
    const res = source === "cache" ? await cache.match(path) : await fetch(path, { cache: "no-store" }).catch(() => null);
    if (!res || !res.ok) continue;
    const buf = await res.arrayBuffer();
    if ((await hashOf(buf)) !== PINNED[path]) continue;
    if (source === "network") await cache.put(path, new Response(buf));
    return new Response(buf, { headers: HEADERS[path] });
  }
  return new Response("PWX runtime file failed its integrity check", { status: 503 });
}

self.addEventListener("install", (e) => {
  e.waitUntil(Promise.all(Object.keys(PINNED).map((p) => runtimeFile(p))).then(() => self.skipWaiting()));
});
self.addEventListener("activate", (e) => e.waitUntil(self.clients.claim()));
self.addEventListener("fetch", (e) => {
  const u = new URL(e.request.url);
  if (u.origin !== self.location.origin) return;
  if (e.request.mode === "navigate" && FRAME_ONLY(u.pathname) && e.request.destination !== "iframe") {
    e.respondWith(new Response("PWX pages only open inside the PWX loader.", { status: 403 }));
    return;
  }
  if (u.pathname.startsWith("/app/")) {
    e.respondWith((async () => {
      const hit = await caches.match(u.pathname, { cacheName: "pwx-verified" });
      return hit ?? new Response("not a verified file", { status: 404 });
    })());
  } else if (PINNED[u.pathname]) {
    e.respondWith(runtimeFile(u.pathname));
  }
});
